def welcome(name: str | None = None) -> str:
    if name is None:
        return "Welcome, guest!"
    return "Welcome, " + name + "!"

print(welcome())          # Welcome, guest!
print(welcome("Sara"))    # Welcome, Sara!

def shout(func):
    def wrapper():
        return func().upper() + "!"
    return wrapper

@shout
def hello():
    return "hello"

print(hello())    # HELLO!

